import json, urllib.request, os

def get(url):
    req = urllib.request.Request(url, headers={'Authorization': 'Bearer ' + os.environ['GH_TOKEN'], 'Accept': 'application/vnd.github+json'})
    return json.load(urllib.request.urlopen(req))

d = get('https://api.github.com/repos/IstiN/flutter_agent_harness/actions/runs/43371867801')
print('ticket run:', d['id'], d['status'], d['conclusion'], '| attempt:', d.get('run_attempt'))

from datetime import datetime, timedelta, timezone
cutoff = (datetime.now(timezone.utc) - timedelta(minutes=20)).strftime('%Y-%m-%dT%H:%M:%S')
recent = get(f'https://api.github.com/repos/IstiN/flutter_agent_harness/actions/runs?per_page=40&created=>{cutoff}')['workflow_runs']
print(f'=== fa-m5 jobs since {cutoff} (now ~{datetime.now(timezone.utc).strftime("%H:%M")}):')
found = False
for r in recent:
    try:
        jobs = get(f"https://api.github.com/repos/IstiN/flutter_agent_harness/actions/runs/{r['id']}/jobs?per_page=100").get('jobs', [])
        for j in jobs:
            rn = j.get('runner_name') or ''
            if rn.startswith('fa-m5'):
                found = True
                print(f"  {j.get('started_at')} | run {r['id']} | {j['name'][:42]:42s} | {rn} | {j.get('conclusion') or j.get('status')}")
    except Exception as e:
        print('  ERR', r['id'], e)
if not found:
    print('  (no fa-m5 jobs since cutoff)')

